#!/usr/bin/env python3
"""Generate all active numerical reporting from independently audited S02 data."""
import argparse
import hashlib
import itertools
import json
import statistics
from pathlib import Path
from test_oracle import verify_dataset
ROOT=Path(__file__).resolve().parent
FROZEN_RUBRIC_SHA256="b220e94331fa59e205929890be1f68f1a876e3d728b32c3535a3012970d87353"
ARMS={('Binary','Fixed','Stochastic'):'Model A',('Ternary','Fixed','Stochastic'):'Model B',('Binary','AdaptiveLocal','Stochastic'):'Model C',('Ternary','AdaptiveLocal','Stochastic'):'Model D',('Binary','CentralizedAdaptive','Stochastic'):'Central heuristic',('Binary','RandomAdaptive','Stochastic'):'Random control',('Binary','AdaptiveLocal','Deterministic'):'Zero-T control'}

def analyze(results,traces):
    verification=verify_dataset(results,traces)
    data=json.loads(results.read_text(encoding="utf-8"));rows=data['runs'];means=[]
    for arm,name in ARMS.items():
        def select(cost):return [x for x in rows if (x['element_type'],x['topology_type'],x['dynamics_type'])==arm and x['num_nodes']==16 and x['temperature']==.5 and x['cost_topology_update']==cost]
        selected=select(.5);expensive=select(5)
        mean=lambda key:statistics.mean(x[key] for x in selected)
        means.append({'arm':name,'n':len(selected),'mean_task_gap':mean('energy_error'),'mean_comm_ops':mean('comm_ops'),'mean_edge_edits':mean('topology_update_ops'),'mean_proxy_cost_0_5':mean('total_cost'),'mean_proxy_cost_5':statistics.mean(x['total_cost'] for x in expensive),'ground_state_occupancy_fraction':mean('ground_state_occupancy_fraction'),'mean_network_task_energy_difference':statistics.mean(x['final_network_energy']-x['final_energy'] for x in selected)})
    pairs=[]
    # Descriptive paired effects; no post-hoc significance/architecture test.
    for candidate,baseline in [('Model C','Model A'),('Model D','Model B'),('Model C','Zero-T control'),('Central heuristic','Model A'),('Random control','Model A')]:
        for n,T in itertools.product([8,12,16],[.1,.5,1]):
            armrow=lambda name,seed:next(x for x in rows if ARMS[(x['element_type'],x['topology_type'],x['dynamics_type'])]==name and x['num_nodes']==n and x['temperature']==T and x['seed']==seed and x['cost_topology_update']==.5)
            deltas=[]
            for seed in range(1,6):
                c,b=armrow(candidate,seed),armrow(baseline,seed)
                deltas.append({'seed':seed,'task_gap_difference':c['energy_error']-b['energy_error'],'proxy_cost_difference':c['total_cost']-b['total_cost']})
            pairs.append({'candidate':candidate,'baseline':baseline,'num_nodes':n,'temperature':T,'n_problem_seeds':5,'mean_task_gap_difference':statistics.mean(x['task_gap_difference'] for x in deltas),'mean_proxy_cost_difference':statistics.mean(x['proxy_cost_difference'] for x in deltas),'lower_task_gap_count':sum(x['task_gap_difference'] < -1e-9 for x in deltas),'equal_task_gap_count':sum(abs(x['task_gap_difference'])<=1e-9 for x in deltas),'higher_task_gap_count':sum(x['task_gap_difference'] > 1e-9 for x in deltas),'paired_outcomes':deltas})
    planned={'nodes':[8,12,16,24],'seeds':list(range(1,11)),'temperatures':[.1,.5,1,2],'couplings':[.5,1,1.5],'topology_costs':[0,.5,1,2,5,10],'arms':7}
    actual={k:sorted({x[field] for x in rows}) for k,field in [('nodes','num_nodes'),('seeds','seed'),('temperatures','temperature'),('couplings','coupling_scale'),('topology_costs','cost_topology_update')]};actual['arms']=len(ARMS)
    coverage={'planned_vertex_matched_rows':20160,'executed_priced_rows':len(rows),'unexecuted_rows':20160-len(rows),'fraction_of_planned_vertex_grid':len(rows)/20160,'planned':planned,'executed':actual,'omitted_values':{k:sorted(set(planned[k])-set(actual[k])) for k in ['nodes','seeds','temperatures','couplings','topology_costs']},'capacity_matched':'UNTESTED; adding unused nodes is not a matched-task comparison','field_interval_deviation':'Original specification [-1,1]; original methodology/code and corrected pilot [-0.5,0.5]. No claim of testing the wider field distribution.'}
    freeze=json.loads((ROOT/'evidence/rubric-freeze.json').read_text(encoding="utf-8"));frozen=ROOT/'evidence/S02_EVALUATION_RUBRIC.frozen.md'
    if freeze['sha256']!=FROZEN_RUBRIC_SHA256 or hashlib.sha256(frozen.read_bytes()).hexdigest()!=FROZEN_RUBRIC_SHA256:raise ValueError('frozen rubric changed')
    rubric=[{'gate':'Complete implemented dynamics and task identity','status':'PASS FOR DOCUMENTED BOUNDED HEURISTICS','evidence':'Immutable task coefficients and complete state traces independently audited; actual proposals and scheduling documented.'},{'gate':'Equilibrium/ergodic sampling guarantees','status':'NOT CLAIMED','evidence':'Adaptive arms are nonequilibrium optimizers; occupancy fraction is not ESS. Fixed tiny-state Metropolis controls are checked separately.'},{'gate':'Capacity/rule-matched architectural comparison','status':'NOT MET','evidence':'Vertex-matched only; H2 explicitly untested; capacity flag rejects.'},{'gate':'Complete cost matching','status':'NOT MET','evidence':'Three-term proxy omits weighting/timing of full energy scans, global sorting, RNG, setup/validation and graph storage; auxiliary operation counts disclosed.'},{'gate':'Strong baseline/ablation portfolio','status':'NOT MET','evidence':'Central correlation-ranking heuristic is not a strong optimized topology/inference portfolio; no trained-frozen, matched binary encoding or full factorial.'},{'gate':'Independent instances/power/confirmatory statistics','status':'NOT MET','evidence':'Five seeds per size; below reviewer planning floor; no pre-unblinding power calculation. Repriced rows/temperature duplicates do not add replication.'},{'gate':'Frozen >=20% full-cost materiality and simultaneous 95% interval','status':'NOT EVALUABLE','evidence':'Matched quality/full cost, strong baseline and independent-instance power prerequisites absent. Criterion unchanged, not replaced with a favorable endpoint.'},{'gate':'Provenance and reproducibility','status':'PASS FOR RECORDED LOCAL RUN','evidence':'Original files preserved; all corrected rows, task coefficients, traces, source hashes and verification commands retained.'},{'gate':'Physical hardware advantage','status':'UNTESTED','evidence':'No measured joules, hardware realization or area/delay data.'}]
    return {'decision':'REVISE','decision_basis':'Corrected pilot measurements do not satisfy unchanged architectural-evidence gates; no acceptance/rejection of H2 or Track S termination is warranted.','hypotheses':{'H1':{'status':'DESCRIPTIVE_ONLY','comparison':'Model C versus zero-T adaptive control; seeded random scan remains; not proof of general architectural exploration efficiency.'},'H2':{'status':'UNTESTED','comparison':'No task/capacity-matched binary-versus-ternary experiment.'},'H3':{'status':'DESCRIPTIVE_ONLY','comparison':'Same-task local versus fixed heuristics; cost proxy and baseline portfolio incomplete, full architectural advantage untested.'}},'data_sha256':hashlib.sha256(results.read_bytes()).hexdigest(),'traces_sha256':hashlib.sha256(traces.read_bytes()).hexdigest(),'oracle_verification':verification,'scope':coverage,'simulated_trajectories':data['simulated_trajectories'],'tables':{'original_slice_N16_T0_5':means},'paired_descriptive_effects':pairs,'rubric':rubric,'rubric_sha256':freeze['sha256'],'statistics':'No p-values, confirmatory confidence claims or equivalence conclusions; five-seed descriptive paired outcomes only.'}

def render(analysis):
    a=analysis;lines=['# S02 corrected research report','', '**Decision: REVISE.** The original STOP verdict and numerical claims are superseded. The corrected bounded pilot supports descriptive comparisons of the implemented heuristics; it does not establish or falsify a general ternary/stochastic/adaptive architectural advantage.', '', '**H2 — UNTESTED**. All runs are vertex-matched. No dummy-node or capacity-matched result is claimed. H1 and H3 have descriptive pilot observations only; the unchanged rubric does not permit a confirmatory architecture verdict from this scope.', '', '## Verified experiment and objective','', 'There are 15 immutable problem instances (five seeds at each of N=8,12,16), 315 simulated trajectories and 1260 cost-repriced rows. Each trajectory has its initial state plus 200 post-proposal states; all 63315 states are audited with a separate Python task-energy evaluator. Every row uses its own coefficient-specific exact ground reference. Maximum observed C++/Python reference difference: '+format(a['oracle_verification']['max_cpp_python_reference_difference'],'.17g')+'. This is the observed local result, not a cross-platform certification.', '', 'The task Hamiltonian uses the original problem h/J throughout. Computational edges/couplings may change proposal dynamics but cannot redefine success. Adaptive arms are nonequilibrium optimization heuristics, not equilibrium samplers of the task distribution. Ground-state occupancy is not ESS or a count of independent samples. The ternary ground reference equals the binary endpoint minimum for this multi-affine Hamiltonian; tiny independent 3^N enumeration controls check that theorem. It says nothing about comparative dynamics or H2.', '', '## Quantitative table generated from data','', 'Same slice as the original report: N=16, T=0.5, five problem seeds. Gaps are final immutable-task energy minus the correct per-instance optimum. Cost is the declared partial software proxy, not measured runtime/energy. Costs 0.5 and 5 reprice identical trajectories.', '', '| Arm | Mean task gap | Mean comm ops | Mean edge edits | Mean proxy cost 0.5 | Mean proxy cost 5 |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for r in a['tables']['original_slice_N16_T0_5']:lines.append('| '+r['arm']+' | '+f"{r['mean_task_gap']:.6f} | {r['mean_comm_ops']:.3f} | {r['mean_edge_edits']:.3f} | {r['mean_proxy_cost_0_5']:.3f} | {r['mean_proxy_cost_5']:.3f} |")
    lines+=['','## Paired descriptive observations','','Negative task-gap difference favors the candidate. Pairs use the same problem and T at C_top=0.5; n=5 seeds. Repricing does not add trials. The full 45 comparisons across sizes/temperatures are in analysis.json; this display retains the original report slice rather than choosing a favorable new one.','','| Candidate / baseline | Mean gap difference | Lower / equal / higher gap counts | Mean proxy-cost difference |','| --- | ---: | --- | ---: |']
    for p in a['paired_descriptive_effects']:
        if p['num_nodes']==16 and p['temperature']==.5:lines.append('| '+p['candidate']+' / '+p['baseline']+' | '+f"{p['mean_task_gap_difference']:.6f} | {p['lower_task_gap_count']} / {p['equal_task_gap_count']} / {p['higher_task_gap_count']} | {p['mean_proxy_cost_difference']:.3f} |")
    lines+=['','These differences are observations on the corrected five-seed subset. There is no reported p>0.35, 18% capacity-matched convergence penalty, universal topology tax or statistically established absence of advantage. Failure to establish an advantage here is not equivalence and does not terminate Track S.', '', '## Predefined sweep versus actual scope','', 'Original predefined vertex-matched grid: 20160 priced rows. Corrected execution: 1260 rows (6.25%), leaving 18900 unexecuted. The same original subset is regenerated; it is not relabeled as the complete predefined experiment.', '', '| Axis | Predefined | Executed | Omitted |','| --- | --- | --- | --- |']
    for key in ['nodes','seeds','temperatures','couplings','topology_costs']:lines.append('| '+key+' | '+str(a['scope']['planned'][key])+' | '+str(a['scope']['executed'][key])+' | '+str(a['scope']['omitted_values'][key])+' |')
    lines+=['', 'The original specification stated fields in [-1,1]; original code/methodology used [-0.5,0.5]. This pilot preserves the implemented interval and explicitly does not test the wider one. N24 is outside this bounded exact-reference execution. Capacity-matched task design remains absent. Temperature labels on the zero-T control do not change its acceptance policy and are not additional independent evidence.', '', '## Unchanged independent rubric','', 'The original frozen rubric SHA-256 is `'+a['rubric_sha256']+'`. Its >=20% full-cost improvement and simultaneous 95% interval criterion is retained. It is **not evaluable** after the missing capacity/quality/cost/baseline/power prerequisites; no new weaker criterion replaces it. The reviewer planning floor is at least 30 independent held-out instances per workload stratum plus a pre-unblinding power calculation; five seeds do not pass. No new confirmatory p-value is manufactured.', '', '| Gate | Assessment | Evidence/limit |','| --- | --- | --- |']
    for g in a['rubric']:lines.append('| '+g['gate']+' | '+g['status']+' | '+g['evidence']+' |')
    lines+=['','## Scientific interpretation','','The corrected implementation repairs demonstrated validity defects. The dataset measures task-energy outcomes, occupancy and declared proxy operations for the actual seven heuristics. It does not measure hardware advantage, total-system cost, a full baseline portfolio or H2. Local rewiring, central ranking and random rewiring can trade task quality against internal-network dynamics; those are not changes to the task itself. Centralized means a global pair-ranking heuristic here, not spectral min-cut or an exact/strong optimizer. Deterministic means zero-temperature acceptance conditional on seeded random scan/proposals, not the absence of randomness in scheduling.', '', '**REVISE** is warranted because architectural claims remain underidentified and the completed pilot misses explicit rubric gates. CONTINUE would require a validated advantage against the required matched controls; STOP would require valid evidence sufficient to reject the declared hypothesis/domain. Neither follows from this partial five-seed proxy-cost experiment. H2 is untested, not negative evidence. No S03 or further research cycle is initiated.', '', '## Provenance and reproduction','','All original PR #582 files, results and STOP text remain byte-identical in historical/pr582/ with a superseded-evidence notice and manifest. Before-fix rejection tests and actual review comments are in evidence/before/ and evidence/pr582-*.json; after-fix controls/oracle evidence are in evidence/after/. Raw corrected states are in results.traces.jsonl.gz, and task coefficients plus all 1260 rows are in results.json. Run `python3 regenerate.py --runner /path/to/t81_s02_stochastic_topology` to regenerate, audit and render this report/analysis. SHA-256 identities and recorded commands are in evidence/generation.json. No production runtime, ISA, language or governance mechanism was modified.']
    return '\n'.join(lines)+'\n'

def main():
    p=argparse.ArgumentParser();p.add_argument('--results',type=Path,default=ROOT/'results.json');p.add_argument('--traces',type=Path,default=ROOT/'results.traces.jsonl.gz');p.add_argument('--output',type=Path,default=ROOT/'analysis.json');p.add_argument('--report',type=Path,default=ROOT/'RESEARCH_REPORT.md');p.add_argument('--check',action='store_true');args=p.parse_args()
    a=analyze(args.results,args.traces);text=render(a);raw=json.dumps(a,indent=2)+'\n'
    if args.check:
        if args.output.read_text(encoding="utf-8")!=raw or args.report.read_text(encoding="utf-8")!=text:raise SystemExit('analysis/report stale relative to audited data')
    else:args.output.write_text(raw, encoding="utf-8");args.report.write_text(text, encoding="utf-8")
    print(json.dumps({'decision':a['decision'],'rows':a['scope']['executed_priced_rows'],'H2':a['hypotheses']['H2']['status'],'report_matches_data':True}))
if __name__=='__main__':main()
